export const dynamic = "force-dynamic";

export default async function DashboardPage() {
  const [totalItems, totalValue, lowStockItems, expiringItems, recentTxns] =
    await Promise.all([
      prisma.item.count(),
      prisma.item.aggregate({
        _sum: { quantity: true },
        _count: true,
      }),
      prisma.item.findMany({
        where: {
          safetyStock: { gt: 0 },
          quantity: { lte: prisma.item.fields.safetyStock },
        },
        orderBy: { quantity: "asc" },
        take: 10,
      }),
      prisma.item.findMany({
        where: {
          warrantyEnd: {
            gte: new Date(),
            lte: new Date(Date.now() + 30 * 24 * 60 * 60 * 1000),
          },
        },
        orderBy: { warrantyEnd: "asc" },
        take: 10,
      }),
      prisma.transaction.findMany({
        orderBy: { createdAt: "desc" },
        take: 10,
        include: { item: { select: { name: true, code: true, unit: true } } },
      }),
    ]);

  // 计算本月出入库
  const now = new Date();
  const startOfMonth = new Date(now.getFullYear(), now.getMonth(), 1);
  const monthTxns = await prisma.transaction.groupBy({
    by: ["type"],
    where: { createdAt: { gte: startOfMonth } },
