                  value={form.categoryId}
                  onValueChange={(v) => update("categoryId", v)}
                >
                  <SelectTrigger>
                    <SelectValue placeholder="选择分类" />
                  </SelectTrigger>
                  <SelectContent>
                    {categories.map((c) => (
