"use client";

import { useState, useEffect } from "react";
import {
  Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import {
  Select, SelectContent, SelectItem, SelectTrigger, SelectValue,
} from "@/components/ui/select";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";

interface Item {
  id?: string;
  code: string;
  name: string;
  description?: string;
  sn?: string;
  model?: string;
  manufacturer?: string;
  categoryId: string;
  unit: string;
  quantity?: number;
  safetyStock?: number;
  position?: string;
  supplier?: string;
  price?: number;
  warrantyStart?: string;
  warrantyEnd?: string;
  nandType?: string;
  compatibleProducts?: string;
}

interface Category {
  id: string;
  name: string;
  parentId: string | null;
}

interface Props {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  item?: Item | null;
  categories: Category[];
  onSaved: () => void;
}

export function ItemFormDialog({
  open, onOpenChange, item, categories, onSaved,
}: Props) {
  const [form, setForm] = useState<Item>({
    code: "", name: "", categoryId: "", unit: "个",
  });
  const [saving, setSaving] = useState(false);

  useEffect(() => {
    if (item) {
      setForm({
        ...item,
        warrantyStart: item.warrantyStart?.split("T")[0] ?? "",
        warrantyEnd: item.warrantyEnd?.split("T")[0] ?? "",
      });
    } else {
      setForm({ code: "", name: "", categoryId: "", unit: "个" });
    }
  }, [item, open]);

  const update = (key: keyof Item, value: string | number) => {
